        val -> System.out.println("  Success: " + val)
    );

    Either<String, Integer> failure = Either.left("Invalid input");
    failure.fold(
        err -> System.out.println("  Error: " + err),
        val -> System.out.println("  Success: " + val)
    );
    System.out.println();
  }

